{
  "goal": "Deliver the one-room MVP that securely turns a RoomPlan bedroom scan into a canonical, versioned, constraint-aware scene with phone-to-web handoff, a three-pane web editor, typed conversational edits, deterministic validation, quick render, photoreal output tied to immutable scene state, single-step undo, and optional non-blocking splat preview.",
  "steps": [
    {
      "id": "step-1",
      "title": "Finalize the authoritative scene schema and semantic model",
      "description": "Freeze the canonical room/scene schema, entity semantics, supported object classes, typed operation shapes, and invariants so every surface implements the same contract from `SceneState` down to `AssetRef` and `DerivedState`.",
      "requiredChecks": [
        "noop"
      ],
      "highStakes": true
    },
    {
      "id": "step-2",
      "title": "Define scene snapshots, versioning boundaries, and undo semantics",
      "description": "Define the immutable `SceneSnapshot` + mutable `SceneHead` model, version increment rules, sidecar boundaries, and one-step undo behavior so every edit is reconstructable and no non-authoritative artifact can drift into scene history.",
      "requiredChecks": [
        "noop"
      ],
      "highStakes": true
    },
    {
      "id": "step-3",
      "title": "Define the secure handoff and server-authoritative API contract",
      "description": "Define the one-time handoff grant, scene-scoped session model, upload-token rules, idempotent API contracts, reason codes, and plan/apply authority boundaries so raw `scene_id` possession is never enough to mutate or read a scene.",
      "requiredChecks": [
        "noop"
      ],
      "highStakes": true
    },
    {
      "id": "step-4",
      "title": "Bootstrap the implementation workspace, shared contracts, and fixture scenes",
      "description": "Because the repository is docs-only today, first create the real implementation surfaces: a minimal workspace for `ios/`, `apps/web/`, `apps/api/`, and a shared contracts package that mirrors the finalized PRD type names; add database migrations for `SceneHead`, `SceneSnapshot`, sidecars, handoff grants, jobs, and idempotency records; seed RoomPlan fixture payloads plus golden canonical-scene outputs so backend and web work can proceed fixture-first before device capture is complete. This is the fastest path because it unblocks parallel development without waiting on Swift capture hardware loops.",
      "requiredChecks": [
        "noop"
      ]
    },
    {
      "id": "step-5",
      "title": "Implement RoomPlan capture, ingest, and initial scene creation",
      "description": "Build the native RoomPlan companion flow and the synchronous ingest path behind `POST /captures/roomplan`: serialize `RoomPlanCaptureRequest`, validate single-bedroom captures, map shell/openings/surfaces into canonical coordinates, assign stable IDs exactly once, preserve unsupported detections as `generic_obstacle`, attach initial asset refs or proxies, compute the first `derived_state_cache`, persist `SceneSnapshot(scene_version = 1)` + `SceneHead`, issue the one-time web handoff, and return the optional `video_upload_token` without blocking editor readiness.",
      "requiredChecks": [
        "noop"
      ],
      "highStakes": true
    },
    {
      "id": "step-6",
      "title": "Stand up scene reads and the initial web editor shell",
      "description": "Implement `POST /handoffs/redeem`, scene-scoped web sessions, and `GET /scenes/{scene_id}` so the editor loads only from canonical persisted scene data; then build the first three-pane web shell with scan/layout/render placeholders, current-selection state, scene version display, rejection messaging hooks, and refresh/reload behavior that always reflects the latest committed snapshot instead of any client-local draft state.",
      "requiredChecks": [
        "noop"
      ],
      "highStakes": true
    },
    {
      "id": "step-7",
      "title": "Add asset retrieval, proxy fallback, and quick rendering",
      "description": "Ingest the curated glTF manifest, implement class/style/dimension-based asset resolution plus deterministic proxy fallback, and wire the layout and render panes to the current scene snapshot so object footprints, labels, selection highlights, and quick-render geometry update in under the MVP budget after every committed change. Keep asset misses non-blocking and log-only so editing never stalls on retrieval.",
      "requiredChecks": [
        "noop"
      ]
    },
    {
      "id": "step-8",
      "title": "Implement the deterministic mutation pipeline: validation, apply, locking, and undo",
      "description": "Build the server-side executor for supported typed scene operations and expose authoritative `POST /scenes/{scene_id}/apply` and `POST /scenes/{scene_id}/undo` flows. On every accepted mutation, enforce schema/target/version/lock checks, simulate the full plan, run hard constraints and soft-score recomputation, regenerate `derived_state_cache`, commit a new immutable snapshot atomically, update `undo_base_snapshot_id`, and surface machine-readable reason codes for stale versions, locks, overlaps, opening blockage, clearance failures, anchor violations, and undo unavailability.",
      "requiredChecks": [
        "noop"
      ],
      "highStakes": true
    },
    {
      "id": "step-9",
      "title": "Build the LLM planner and chat-driven edit workflow",
      "description": "Implement `POST /scenes/{scene_id}/plan`, prompt assembly from compact scene summaries + selection context + asset manifest, structured planner outputs constrained to `operation_plan_preview`, `command_request`, `clarification_request`, or `rejection`, and a chat UI that supports selection-grounded references like “this wall” and “that chair.” Keep the model non-authoritative: the client can only accept or reject server-issued previews, and dedicated commands such as photoreal/undo must route through their own endpoints.",
      "requiredChecks": [
        "noop"
      ]
    },
    {
      "id": "step-10",
      "title": "Ship photoreal generation, bookmarks, and version-linked gallery storage",
      "description": "Add bookmark sidecars, high-resolution conditioning render outputs (RGB/depth/edge), provider integration for `POST /scenes/{scene_id}/photoreal`, and gallery storage keyed to immutable `scene_version` + `scene_snapshot_id`. Expose button-triggered and chat-triggered generation from the current camera or saved bookmarks, keep retries idempotent, and ensure photoreal jobs never mutate editable scene state or participate in undo history.",
      "requiredChecks": [
        "noop"
      ]
    },
    {
      "id": "step-11",
      "title": "Add asynchronous splat jobs and scan-pane swap behavior",
      "description": "Implement the optional raw-video upload path at `POST /captures/{scene_id}/video`, validate the scene-scoped one-time `video_upload_token`, queue background splat training, store/update the `SplatAssetRecord` sidecar, and make the scan pane visibly switch from RoomPlan placeholder to splat only when job state becomes `ready`. Keep the editor fully usable when no video is uploaded or when splat processing fails.",
      "requiredChecks": [
        "noop"
      ],
      "highStakes": true
    },
    {
      "id": "step-12",
      "title": "Add observability, evaluation harnesses, and demo hardening",
      "description": "Backfill structured logs, metrics, and trace points for ingest latency, planner behavior, validation reason codes, asset misses, photoreal latency/failures, and splat job duration; add fixture-driven regression suites and scripted end-to-end demos covering valid/invalid edits, stale-version conflicts, undo, and scene reload; then harden scene deletion, retry behavior, empty/error states, seeded demo scans, and presentation polish so the one-room MVP is reliable on real bedroom scans.",
      "requiredChecks": [
        "noop"
      ]
    }
  ]
}

